import { readFileSync, writeFileSync } from 'node:fs';

const F = '/workspace/probe/corpus/gen_errors-malformed.mjs';
let src = readFileSync(F, 'utf8');

// name -> hex, for the control chars used by the generator
const NAMES = {
  SOH: '0001', STX: '0002', ETX: '0003', ACK: '0006', BEL: '0007',
  VT: '000b', DLE: '0010', DC1: '0011', DC2: '0012', US: '001f',
  ESC: '001b', DEL: '007f', NEL: '0085',
};

// Rewrite `const X = '<literal ctrl>';` into `const X = CC('00xx');`
for (const [name, hex] of Object.entries(NAMES)) {
  const re = new RegExp("const " + name + " = '[^']*';");
  if (!re.test(src)) throw new Error('no const decl for ' + name);
  src = src.replace(re, "const " + name + " = CC('" + hex + "');");
}

// the stray non-ascii byte used for the !!binary ascii-decode failure case
src = src.replace('\'x: !!binary "é"\'', '\'x: !!binary "\' + CC(\'00e9\') + \'"\'');

// verify no literal control characters / non-ascii remain in the source
const bad = [];
for (let i = 0; i < src.length; i++) {
  const c = src.codePointAt(i);
  if (c === 0x0a) continue;
  if (c < 0x20 || c === 0x7f || c > 0x7e) bad.push([i, c.toString(16)]);
}
if (bad.length) throw new Error('literal control/non-ascii still present: ' + JSON.stringify(bad.slice(0, 20)));

writeFileSync(F, src);
console.log('patched; source is now pure printable ASCII');

